use std::collections::BTreeMap;
use std::sync::Arc;
use trail::blockchain::{
    block::{Block, Body},
    path::TransactionPaths,
    transaction::Transaction,
};
use trail::consensus::{
    trail::{TrailConfig, TrailConsensus},
    Consensus, Validator, ValidatorRegistry,
};
use trail::tools::Hasher;
use trail::wallet::Wallet;

#[test]
fn indexed_certificates_match_address_certificate_economics() {
    // Generated by the address-certificate implementation at 8caf1df using
    // these same transactions, paths, stakes, and ordered reductions.
    let baselines = [
        (
            2,
            "974be77eceae65ecc8c826de62cee5af1850ea045a2a23761a64dd128b5c130b",
        ),
        (
            4,
            "eb1fcad9ae35495e10aaeef8b02ddb5d1cd61538caac20d05136352f0320f683",
        ),
        (
            8,
            "26ce90840320f3926d143bb375e77eeb4855ab7efd6a0b6f2c02c933589955d0",
        ),
        (
            16,
            "406afd688986b2ac400149e9baf689a9f2a54f90c84a51db1bca7b1fb6b89879",
        ),
    ];
    for (hops, expected) in baselines {
        let seed = 0x5450_5300 + hops as u64;
        let wallets: Vec<_> = (0..=hops)
            .map(|i| Wallet::new_deterministic(seed, i as u32))
            .collect();
        let registry = Arc::new(ValidatorRegistry::from_wallets(&wallets).unwrap());
        let transaction = Transaction::with_timestamp(
            wallets[hops].address.clone(),
            hops as i64,
            1.0,
            1.0,
            wallets[0].clone(),
            false,
            1_700_000_000,
        );
        let mut paths = TransactionPaths::new_with_epoch(transaction.clone(), 7);
        for pair in wallets.windows(2) {
            assert!(paths.append_completed_hop(
                pair[1].address.clone(),
                pair[0].clone(),
                pair[1].clone(),
            ));
        }
        let certificate = paths.to_aggregated_signed_paths(&registry).unwrap();
        let block = Block::new(
            1,
            7,
            0,
            String::new(),
            Body::new(vec![transaction], vec![certificate.clone()]),
            wallets[hops].clone(),
        )
        .unwrap();
        assert!(block.verify_path_evidence(0, &registry));
        let validators: Vec<_> = wallets
            .iter()
            .enumerate()
            .map(|(i, wallet)| {
                Validator::new(wallet.address.clone(), (1 + (i + 5) * 3 % 13) as f64, 1.0)
            })
            .collect();
        if hops > 2 {
            let config = TrailConfig {
                max_path_hops: 2,
                ..TrailConfig::default()
            };
            let mut limited = TrailConsensus::new(0.1, config, registry.clone()).unwrap();
            assert_eq!(
                limited
                    .compute_block_rewards(&block, &validators)
                    .relay_reward,
                0.0
            );
            limited.on_epoch_end(std::slice::from_ref(&block), &validators);
            assert!(limited.score_history().values().all(|score| *score == 0.0));
        }
        let mut consensus = TrailConsensus::new(0.1, TrailConfig::default(), registry).unwrap();
        consensus.enable_deterministic_reductions();
        let plan = consensus.compute_block_rewards(&block, &validators);
        assert!(plan.relay_reward > 0.0);
        consensus.on_epoch_end(&[block], &validators);
        consensus.on_epoch_end(&[], &validators);
        let snapshot = consensus.metrics_snapshot();
        assert!(snapshot.score_history.values().any(|score| *score > 0.0));
        let actual = serde_json::to_vec(&(
            &certificate.signature,
            plan.rewards,
            plan.proposer_reward,
            plan.relay_reward,
            plan.burned_relay_fee,
            plan.total_fee,
            snapshot
                .latest_score_history
                .into_iter()
                .collect::<BTreeMap<_, _>>(),
            snapshot
                .score_history
                .into_iter()
                .collect::<BTreeMap<_, _>>(),
            snapshot
                .normalized_score
                .into_iter()
                .collect::<BTreeMap<_, _>>(),
            snapshot
                .unnormalized_proposer_weights
                .into_iter()
                .collect::<BTreeMap<_, _>>(),
            snapshot
                .normalized_proposer_weights
                .into_iter()
                .collect::<BTreeMap<_, _>>(),
        ))
        .unwrap();
        assert_eq!(hex::encode(Hasher::hash(actual)), expected, "{hops} hops");
    }
}
